    """Extend the seed rows beside solid 5 boundary lines."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # A vertical 5 stripe: extend each colored value found at the left seed
    # across the open field to the stripe. The source color is row-specific.
    for c in range(w):
        rows = [r for r in range(h) if g[r][c] == 5]
        if len(rows) >= 2 and rows == list(range(min(rows), max(rows) + 1)):
            top, bottom = min(rows), max(rows)
            # Process seed fields on each side of the stripe.
            for cols in (range(c - 1, -1, -1), range(c + 1, w)):
                data_cols = [x for x in cols if any(g[r][x] not in (0, 5) for r in range(h))]
                if not data_cols:
                    continue
                x0, x1 = min(data_cols), max(data_cols)
                seed_rows = [r for r in range(h) if any(g[r][x] not in (0, 5) for x in range(x0, x1 + 1))]
                # Row-wise colors on a wide field are broadcast across the field.
                if len(data_cols) == 1:
                    x = data_cols[0]
                    for r in range(top, bottom + 1):
                        value = g[r][x]
                        if value not in (0, 5):
                            for xx in range(x0, x1 + 1):
                                if xx != x:
                                    g[r][xx] = value
                elif seed_rows:
                    # Repeated row motif from the colored seed block, aligned
                    # to its original rows and extended through the bounded span.
                    a, b = min(seed_rows), max(seed_rows)
                    motif = [[g[r][x] for x in range(x0, x1 + 1)] for r in range(a, b + 1)]
                    for r in range(max(top, a), min(bottom, h - 1) + 1):
                        src = motif[(r - a) % len(motif)]
                        for j, x in enumerate(range(x0, x1 + 1)):
                            if src[j] not in (0, 5):
                                g[r][x] = src[j]
            return g

    # Horizontal 5 stripe: repeat a seed block of colored rows down/across
    # the open region. (Used for demonstrations whose marker is horizontal.)
    for r in range(h):
        cols = [c for c, value in enumerate(g[r]) if value == 5]
        if len(cols) < 2 or cols != list(range(min(cols), max(cols) + 1)):
